const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '选择题第1题' },
      { kind: 'text', payload: '选择题第2题' },
      { kind: 'text', payload: '说明：本图为语义清图，仅保留已确认的印刷题号与文字，非原扫描像素修复。' }
    ];
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var pad = Math.max(16, Math.round(Math.min(W, H) * 0.08));

    var bg = [['M', 0, 0], ['L', W, 0], ['L', W, H], ['L', 0, H], ['Z']];

    var y1 = Math.round(H * 0.32);
    var y2 = Math.round(H * 0.55);
    var yNote = Math.round(H * 0.88);

    return {
      schemaVersion: 1,
      sceneId: 'semantic-clean-sheet',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: [
        { id: 'sheet-bg', commands: bg }
      ],
      root: {
        type: 'group',
        children: [
          { type: 'path', pathId: 'sheet-bg', fill: '#FFFFFF' },
          {
            type: 'label',
            contentId: metrics[0].contentId,
            anchor: { x: pad, y: y1 },
            hAlign: 'left',
            vAlign: 'middle',
            color: '#1A1A1A'
          },
          {
            type: 'label',
            contentId: metrics[1].contentId,
            anchor: { x: pad, y: y2 },
            hAlign: 'left',
            vAlign: 'middle',
            color: '#1A1A1A'
          },
          {
            type: 'label',
            contentId: metrics[2].contentId,
            anchor: { x: pad, y: yNote },
            hAlign: 'left',
            vAlign: 'middle',
            color: '#6B7280'
          }
        ]
      }
    };
  }
};
